class CRSType(RootModel[Union[str, CRSUri, CRSWKT]]):
    """CRS model.

    Ref: https://github.com/opengeospatial/ogcapi-tiles/blob/master/openapi/schemas/common-geodata/crs.yaml

    Code generated using https://github.com/koxudaxi/datamodel-code-generator/
    """

    root: Union[str, CRSUri, CRSWKT] = Field(..., title="CRS")
    _pyproj_crs: CRS = PrivateAttr()

    def model_post_init(self, __context: Any) -> None:
        """Create Pyproj CRS object from the validated CRS input."""
        if isinstance(self.root, CRSUri):
            crs_input = str(self.root.uri)
        elif isinstance(self.root, CRSWKT):
            crs_input = self.root.wkt
        else:
            crs_input = self.root

        self._pyproj_crs = CRS.from_user_input(crs_input)

    @property
    def __root__(self) -> Union[str, CRSUri, CRSWKT]:
        """Return the raw CRS value (alias of ``root`` kept for existing callers)."""
        return self.root

